# Remove YAML frontmatter if present
skip_yaml_frontmatter <- function(x) {
  content_start <- 1
  if (length(x) > 0 && x[1] == "---") {
    yaml_end <- which(x == "---")
    if (length(yaml_end) >= 2) {
      content_start <- yaml_end[2] + 1
    }
  }
  x[content_start:length(x)]
}

